class NamedList extends Array {
  static get [Symbol.species]() {
    return Array;
  }
  constructor(name, ...items) {
    super();
    this.name = name;
    this.push(...items);
  }
}

const list = new NamedList("nums", 4, 8, 12);
const part = list.slice(1);

console.log(list.name);
console.log(part instanceof NamedList);
console.log(Array.isArray(part));
console.log(part.join(","));
